/** Dataset manifest types & loader (generated by scripts/collect-audio.mjs) */

export interface ClipMeta {
  file: string;
  title: string;
  source?: string;
  sourceUrl?: string;
  recordist?: string;
}

export interface LabelMeta {
  id: string;
  /** Display name */
  label: string;
  /** Subtitle (region / species etc.) */
  sub?: string;
  latin?: string;
  desc?: string;
  source?: string;
  clips: ClipMeta[];
}

import { media } from '@/lib/paths';

export interface Manifest {
  generatedAt: string;
  birds: LabelMeta[];
  whales: LabelMeta[];
}

interface RawClip {
  file: string;
  title: string;
  source?: string;
  sourceUrl?: string;
  recordist?: string;
}
interface RawBird {
  id: string;
  zh: string;
  en: string;
  latin: string;
  clips: RawClip[];
}
interface RawWhale {
  id: string;
  name: string;
  region: string;
  desc: string;
  source: string;
  clips: (RawClip & { fname?: string })[];
}

let cache: Manifest | null = null;

export async function loadManifest(): Promise<Manifest> {
  if (cache) return cache;
  const res = await fetch(media('/media/audio/dataset.json'));
  if (!res.ok) throw new Error('Failed to load the dataset manifest');
  const raw = (await res.json()) as { birds: RawBird[]; whales: RawWhale[] };
  const manifest: Manifest = {
    generatedAt: new Date().toISOString(),
    birds: raw.birds
      .filter((b) => b.clips.length > 0)
      .map((b) => ({
        id: b.id,
        label: b.en,
        latin: b.latin,
        desc: `${b.latin} · recordings contributed by the Freesound community (CC0/CC-BY)`,
        source: 'Freesound.org',
        clips: b.clips.map((c) => ({ ...c, file: media(c.file) })),
      })),
    whales: raw.whales
      .filter((w) => w.clips.length > 0)
      .map((w) => ({
        id: w.id,
        label: w.name,
        sub: w.region,
        desc: w.clips.length > 1 ? `${w.desc} (${w.clips.length} recordings total)` : w.desc,
        source: w.source,
        clips: w.clips.map((c) => ({ ...c, file: media(c.file) })),
      })),
  };
  cache = manifest;
  return manifest;
}
